const $=s=>document.querySelector(s),fmt=(n,d=1)=>new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(n),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
