let rows=[],visible=[],selected=null,loadedStart='',loadedEnd='',day='',zoom=1,generation=0,lastRequest=0,activeController=null;
let viewer=null,viewMode='3d',viewerError='',positionEpoch=Date.now(),positionWindow='',positionDays=30,scaleKm=1,referenceKey='',referenceScale=1,referenceEarthRadius=EARTH_RADIUS;
