let provenance={},motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
const filters=()=>({search:$('#search').value,pha:$('#pha-only').checked,maxLd:Number($('#max-distance').value),minSize:Number($('#min-size').value),day,sort:$('#sort').value});
function status(message,kind='live'){$('#feed-status').dataset.state=kind;$('#feed-status').innerHTML='<i></i>'+esc(message);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function renderSummary(){const s=summaries(rows);$('#stat-count').textContent=s.count;$('#stat-closest').innerHTML=s.closest?fmt(s.closest.ld,2)+'<em>LD</em>':'—';$('#stat-close-name').textContent=s.closest?s.closest.name+' · '+fmt(s.closest.km,0)+' km':'No encounters in window';$('#stat-speed').innerHTML=s.fastest!==null?fmt(s.fastest,1)+'<em>km/s</em>':'—';$('#stat-pha').textContent=s.pha;}
function renderTimeline(){const base=filterRows(rows,{...filters(),day:''}),counts=Array.from({length:Math.round((Date.parse(loadedEnd)-Date.parse(loadedStart))/86400000)+1},(_,i)=>({date:addDays(loadedStart,i),count:0}));for(const r of base){const c=counts.find(c=>c.date===r.date);if(c)c.count++;}const max=Math.max(1,...counts.map(c=>c.count));$('#timeline').innerHTML=counts.map(c=>`<button class="day-button ${day===c.date?'active':''}" data-day="${c.date}" aria-pressed="${day===c.date}" aria-label="${esc(shortDate(c.date))}: ${c.count} encounters"><span class="day-count">${c.count}</span><span class="day-bar" style="--height:${Math.max(3,c.count/max*75)}px"></span><span class="day-label">${esc(shortDate(c.date))}</span></button>`).join('');$('#timeline-heading').textContent=day?'Focused on '+shortDate(day):'The flyby forecast';}
function renderDetail(){const r=visible.find(r=>r.key===selected);if(!r){$('#detail-panel').innerHTML=visible.length?'<div class="empty-detail"><span class="eyebrow">SELECT AN ASTEROID</span><h2>Follow a real trajectory.</h2><p>Select a positioned dot or catalog row to see its Earth-relative state and 30-day predicted path. Unavailable positions are omitted.</p></div>':'<div class="empty-detail"><span class="eyebrow">ENCOUNTER PROFILE</span><h2>A quiet patch of sky.</h2><p>No encounters match these filters.</p></div>';return;}$('#detail-panel').innerHTML=`<div class="detail-top"><span class="eyebrow">ENCOUNTER PROFILE</span><span class="selected-chip">SELECTED</span></div><div class="asteroid-art" aria-hidden="true"><div class="rock"></div></div><h2>${esc(r.name)}</h2><span class="classification ${r.pha?'pha':''}"><i class="${r.pha?'amber':'mint'}-dot"></i>${r.pha?'Potentially hazardous':'Not classified as PHA'}</span><p class="object-id">NASA ID ${esc(r.id)} · 3D marker shape is illustrative</p><div id="position-detail" class="position-detail"></div><dl class="detail-metrics"><div><dt>Close approach</dt><dd>${esc(utc(r.epoch))}<span>${r.date.slice(0,4)} · UTC</span></dd></div><div><dt>Miss distance</dt><dd>${fmt(r.ld,2)} LD<span>${fmt(r.km,0)} km · center to center</span></dd></div><div><dt>Estimated diameter</dt><dd>${r.min===null||r.max===null?'Unknown':fmt(r.min,0)+'–'+fmt(r.max,0)+' m'}<span>A range, not an exact measurement</span></dd></div><div><dt>Relative velocity</dt><dd>${fmt(r.speed,2)} km/s<span>${fmt(r.speed*3600,0)} km/h · relative to Earth</span></dd></div></dl><a class="object-link" href="https://ssd.jpl.nasa.gov/tools/sbdb_lookup.html#/?sstr=${encodeURIComponent(r.id)}" target="_blank" rel="noopener noreferrer">View NASA / JPL object <span>↗</span></a><p class="detail-foot">Encounter statistics describe closest approach; the position panel uses the displayed UTC epoch.</p><section id="object-media" class="object-media" aria-label="Asteroid photos and radar imagery"></section>`;renderMedia(r);updatePositionDetail();}
function renderMap2D(){const display=fieldRows(visible,positionEpoch,selected),width=$('#space-map').clientWidth,height=$('#space-map').clientHeight,radius=Math.min(width*.43,height*.43)*zoom;$('#map-points').innerHTML=display.map(r=>{const p=mapPosition(r,Number($('#max-distance').value)),size=markerSize(r);return `<button class="asteroid-point ${size.known?'':'size-unknown'} ${r.pha?'pha':''} ${r.key===selected?'selected':''}" style="--marker-px:${size.pixels}px;left:${width/2+p.x*radius}px;top:${height*.48+p.y*radius}px" title="${esc(size.label)}" data-object="${esc(r.key)}" aria-label="${esc(r.name)}, ${fmt(r.ld,2)} lunar distances, ${esc(size.label)}" aria-pressed="${r.key===selected}"><span class="point-core"></span><span class="point-label">${esc(r.name)} · ${fmt(r.ld,2)} LD · ${esc(size.label)}</span></button>`;}).join('');$('#map-empty').hidden=visible.length>0;$('#space-map').style.setProperty('--zoom',zoom);}
function renderTable(){$('#result-count').textContent=visible.length;$('#asteroid-table').innerHTML=visible.map(r=>`<tr class="${selected===r.key?'selected-row':''}"><td><button class="table-object" data-object="${esc(r.key)}"><span class="rock" aria-hidden="true"></span><span>${esc(r.name)}${reviewedImages[r.id]?.length?'<span class="imaging-badge" title="Confirmed imagery available"> ▧</span>':''}<span class="table-sub">NASA ${esc(r.id)}</span></span></button></td><td>${esc(utc(r.epoch))}<span class="table-sub">${r.date.slice(0,4)}</span></td><td>${fmt(r.ld,2)}<span class="unit">LD</span><span class="table-sub">${fmt(r.km,0)} km</span></td><td>${r.min===null||r.max===null?'Unknown':fmt(r.min,0)+'–'+fmt(r.max,0)+'<span class="unit">m</span>'}</td><td>${fmt(r.speed,2)}<span class="unit">km/s</span></td><td>${r.pha?'<span class="table-pha"><i class="amber-dot"></i>Potentially hazardous</span>':'<span class="table-normal">Not classified as PHA</span>'}</td><td><button class="row-open" data-object="${esc(r.key)}" aria-label="Explore ${esc(r.name)}">↗</button></td></tr>`).join('');$('#table-empty').hidden=visible.length>0;$('#result-note').textContent=`${visible.length} of ${rows.length} Earth encounters${day?' · '+shortDate(day):''}${visible.length>60?' · Up to 60 nearest the position epoch shown in 3D':''}`;$('#download-btn').disabled=!visible.length;}
function render(){visible=filterRows(rows,filters());if(!visible.some(r=>r.key===selected))selected=null;$('#distance-output').textContent=$('#max-distance').value+' LD';$('#size-output').textContent=$('#min-size').value+' m';renderTimeline();renderTable();renderMap();renderDetail();}
function adopt(feed,meta){const data=normalizeFeed(feed);rows=data.rows;loadedStart=meta.start;loadedEnd=meta.end;provenance={...meta,skipped:data.skipped};day='';selected=null;positionDays=Math.round((Date.parse(meta.end)-Date.parse(meta.start))/86400000)+1;$('#all-days').textContent='Show all '+positionDays+' days ↗';configurePositionWindow(meta.start);$('#start-date').value=loadedStart;$('#end-date').textContent=shortDate(loadedEnd);$('#range-title').textContent=shortDate(loadedStart)+' — '+shortDate(loadedEnd)+', '+loadedEnd.slice(0,4);renderSummary();render();$('#data-provenance').textContent=`Source: NASA / JPL NeoWs. Window: ${loadedStart} through ${loadedEnd} (UTC). Retrieved ${new Date(meta.retrieved_at).toISOString()}. ${meta.mode==='live'?'Fetched from NASA during this visit.':meta.mode==='cache'?'Reused a browser cache less than one hour old.':meta.mode==='shared-cache'?'Reused the shared NASA catalog cache, less than one hour old.':'Saved NASA snapshot; this is not a live response.'} ${data.skipped?data.skipped+' incomplete approach records excluded.':''}`;status(meta.mode==='snapshot'?'Saved NASA snapshot · '+shortDate(loadedStart)+'–'+shortDate(loadedEnd):(meta.mode==='cache'||meta.mode==='shared-cache'?'Cached NASA · ':'NASA · ')+new Date(meta.retrieved_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC',meta.mode==='snapshot'?'snapshot':'live');}
async function load(start,{force=false}={}){if(!validDate(start)){toast('Choose a valid date.');return;}if(force&&Date.now()-lastRequest<10000){toast('Please wait a few seconds before refreshing NASA again.');return;}const request=++generation;activeController?.abort();activeController=new AbortController();const end=addDays(start,29),controller=activeController;$('#load-btn').disabled=true;status('Connecting to NASA…');let error='';
 try{if(!force){try{const cache=JSON.parse(localStorage.getItem('perigee-nasa-30d-cache')||'null');if(cache?.start===start&&cache.end===end&&Date.now()-Date.parse(cache.retrieved_at)>=0&&Date.now()-Date.parse(cache.retrieved_at)<3600000){adopt(cache.feed,{...cache,mode:'cache'});return;}}catch{}}
  lastRequest=Date.now();const timer=setTimeout(()=>controller.abort(),60000);let feed,catalog;try{const response=await fetch('/api/catalog?start='+start,{signal:controller.signal});catalog=await response.json();if(!response.ok)throw Error(catalog.error??'NASA catalog unavailable');if(catalog.start!==start||catalog.end!==end)throw Error('Incomplete NASA catalog window');feed=catalog.feed;}finally{clearTimeout(timer);}normalizeFeed(feed);if(request!==generation)return;const meta={start,end,retrieved_at:catalog.retrievedAt,savedAt:Date.now()};adopt(feed,{...meta,mode:catalog.cacheState==='shared'?'shared-cache':'live'});try{localStorage.setItem('perigee-nasa-30d-cache',JSON.stringify({feed,...meta}));}catch{}
 }catch(e){if(request!==generation)return;error=e.name==='AbortError'?'NASA did not respond in time.':e.message;try{const res=await fetch('data/snapshot.json');if(!res.ok)throw Error();const snapshot=await res.json();if(request!==generation)return;adopt(snapshot.feed,{start:snapshot.start,end:snapshot.end,retrieved_at:snapshot.retrieved_at,mode:'snapshot'});toast(error+' Showing saved NASA data for '+snapshot.start+' through '+snapshot.end+'.');}catch{rows=[];loadedStart=start;loadedEnd=end;renderSummary();render();status('NASA unavailable · please retry','error');$('#data-provenance').textContent='No data loaded. '+error;toast('Unable to load NASA or saved data. Please retry.');}}
 finally{if(request===generation)$('#load-btn').disabled=false;}}
$('#date-form').addEventListener('submit',e=>{e.preventDefault();load($('#start-date').value,{force:true});});$('#start-date').addEventListener('change',()=>{if(validDate($('#start-date').value))$('#end-date').textContent=shortDate(addDays($('#start-date').value,29));});for(const id of ['search','pha-only','max-distance','min-size','sort'])$('#'+id).addEventListener(id==='sort'||id==='pha-only'?'change':'input',()=>{if(loadedStart)render();});
$('#reset-filters').addEventListener('click',()=>{$('#search').value='';$('#pha-only').checked=false;$('#max-distance').value=200;$('#min-size').value=0;$('#sort').value='date';day='';if(loadedStart)render();});$('#timeline').addEventListener('click',e=>{const el=e.target.closest('[data-day]');if(el){day=day===el.dataset.day?'':el.dataset.day;render();}});$('#all-days').addEventListener('click',()=>{day='';if(loadedStart)render();});
document.addEventListener('click',e=>{const el=e.target.closest('[data-object]');if(el){selected=el.dataset.object;renderMap();renderTable();renderDetail();if(el.closest('table')){$('#detail-panel').scrollIntoView({behavior:motion?'smooth':'instant',block:'center'});}}});
$('#zoom-in').addEventListener('click',()=>{if(viewMode==='3d'&&viewer)viewer.zoom(1/1.15);else{zoom=Math.min(1.6,zoom+.15);renderMap();}});$('#zoom-out').addEventListener('click',()=>{if(viewMode==='3d'&&viewer)viewer.zoom(1.15);else{zoom=Math.max(.7,zoom-.15);renderMap();}});
$('#download-btn').addEventListener('click',()=>{const blob=new Blob(['\uFEFF'+csvExport(visible)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`NASA-close-approaches-${loadedStart}${day?'-'+day:''}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported '+visible.length+' filtered encounters.');});
const dialog=$('#about-dialog');for(const id of ['about-btn','map-info','pha-info','sources-btn'])$('#'+id).addEventListener('click',()=>dialog.showModal());$('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const canvas=$('#starfield'),ctx=canvas.getContext('2d');let stars=[],frame=0,animation=0;function resize(){const r=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2);canvas.width=r.width*ratio;canvas.height=r.height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);let seed=613;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646;};stars=Array.from({length:95},()=>({x:rand()*r.width,y:rand()*r.height,r:rand()*.8+.2,a:rand()*.35+.1,phase:rand()*6.28}));drawStars();if(loadedStart)renderMap();}
function drawStars(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.clearRect(0,0,w,h);for(const s of stars){ctx.fillStyle=`rgba(190,211,224,${s.a*(motion?.8+.2*Math.sin(frame*.012+s.phase):1)})`;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();}}
function animate(){if(!motion||document.hidden){animation=0;return;}frame++;if(frame%3===0)drawStars();animation=requestAnimationFrame(animate);}function syncMotion(){viewer?.setMotion(motion);$('#motion-btn').setAttribute('aria-pressed',String(motion));$('#motion-btn').textContent=motion?'Ⅱ':'▷';if(motion&&!animation)animate();else if(!motion){cancelAnimationFrame(animation);animation=0;drawStars();}}
$('#motion-btn').addEventListener('click',()=>{motion=!motion;syncMotion();});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&motion&&!animation)animate();});new ResizeObserver(resize).observe($('#space-map'));syncMotion();$('#start-date').value=dateKey();$('#end-date').textContent=shortDate(addDays(dateKey(),29));load(dateKey());


function shownRows(){return fieldRows(visible,positionEpoch,selected);}
function configurePositionWindow(start){{positionWindow=start;ephemeris.reset(start);if(Number(start.slice(0,4))<1962||Number(start.slice(0,4))>2099)ephemeris.paused=true;const first=Date.parse(start+'T00:00:00Z'),last=first+positionDays*86400000-60000,now=Date.now();positionEpoch=now>=first&&now<=last?now:first+12*3600000;$('#live-clock').checked=now>=first&&now<=last;$('#live-clock').disabled=now<first||now>last;}const first=Date.parse(start+'T00:00:00Z');$('#position-time').min=start+'T00:00';$('#position-time').max=new Date(first+positionDays*86400000-60000).toISOString().slice(0,16);$('#position-slider').max=positionDays*1440-1;syncPositionControls();}
function syncPositionControls(){if(!positionWindow)return;$('#position-time').value=new Date(positionEpoch).toISOString().slice(0,16);$('#position-slider').value=Math.round((positionEpoch-Date.parse(positionWindow+'T00:00:00Z'))/60000);$('#position-epoch-label').textContent=new Date(positionEpoch).toISOString().replace('T',' ').slice(0,19)+' UTC';}
function renderMap(){if(!positionWindow)return;const shown=shownRows();if(viewMode==='3d')ephemeris.ensure(shown,selected);else ephemeris.ensure(shown.filter(r=>r.key===selected),selected);const trackSelection=$('#show-path').checked?selected:null,selectedData=trackSelection&&rows.find(r=>r.key===trackSelection),frameKey=positionWindow+'|'+(trackSelection??'')+'|'+(selectedData?ephemeris.data.get(selectedData.id)?.retrievedAt??'pending':'none');if(frameKey!==referenceKey){referenceKey=frameKey;referenceScale=displayScale(rows,ephemeris.data,positionEpoch,trackSelection);const closest=Math.min(...rows.map(r=>r.km).filter(km=>Number.isFinite(km)&&km>0));referenceEarthRadius=Math.min(EARTH_RADIUS,closest/referenceScale*.7);}scaleKm=referenceScale;const positioned=shown.flatMap(r=>{const state=interpolateState(ephemeris.data.get(r.id),positionEpoch);return state?[{...r,scenePosition:physicalPosition(state.position,scaleKm),positionKm:state.km}]:[];});const chosen=visible.find(r=>r.key===selected),vectors=chosen&&ephemeris.data.get(chosen.id),path=vectors&&$('#show-path').checked?futureTrack(vectors,positionEpoch).map(p=>physicalPosition(p.position,scaleKm)):[];
 if(viewer&&viewMode==='3d')viewer.update(positioned,selected,200,path,positionEpoch,referenceEarthRadius);else if(viewMode==='2d')renderMap2D();
 const failed=shown.filter(r=>ephemeris.errors.has(r.id)).length;$('#ephemeris-status').textContent=viewMode==='2d'?'2D schematic: illustrative bearings and log closest-approach distances':`${positioned.length}/${shown.length} JPL positions loaded · ${visible.length} catalog encounters${failed?' · '+failed+' unavailable':''}${ephemeris.paused?' · service paused; retry later':ephemeris.running?' · loading serially':''}`;$('#linear-scale').textContent=viewMode==='3d'?`Equatorial frame · 1 scene unit = ${fmt(scaleKm/384400,2)} LD · Earth enlarged`:'Log distance schematic';$('#map-empty').hidden=viewMode==='3d'?positioned.length>0:visible.length>0;$('#map-empty').textContent=visible.length?(ephemeris.paused?'JPL positions unavailable. Retry later or use the 2D schematic.':ephemeris.running||ephemeris.pending.length?'Loading NASA/JPL coordinates…':'Positions unavailable for these objects; retry later or use 2D.'):'No encounters match these filters.';
}
function updatePositionDetail(){const box=$('#position-detail'),row=visible.find(r=>r.key===selected);if(!box||!row)return;const data=ephemeris.data.get(row.id),state=interpolateState(data,positionEpoch);if(!state){box.innerHTML='<strong>Position not available yet</strong><p>'+esc(ephemeris.errors.get(row.id)??'Loading JPL Horizons vectors. This object has no fabricated position.')+'</p>';return;}box.innerHTML=`<strong>Position at ${esc(new Date(positionEpoch).toISOString().slice(0,16).replace('T',' '))} UTC</strong><p>Earth-center distance: <b>${fmt(state.km/384400,3)} LD</b> · ${fmt(state.km,0)} km</p><p>J2000 ecliptic X / Y / Z (km):<br>${state.position.map(n=>fmt(n,0)).join(' / ')}</p><small>JPL vectors retrieved ${esc(data.retrievedAt.slice(0,19).replace('T',' '))} UTC. Hourly samples; cubic Hermite interpolation. ${$('#show-path').checked?'Selected path: next 30 days, Earth-relative.':'Selected path hidden.'}</small>`;}
function applyPositionEpoch(value,{live=false}={}){if(!live)$('#live-clock').checked=false;const first=Date.parse(positionWindow+'T00:00:00Z'),last=first+positionDays*86400000-60000;if(!Number.isFinite(value)||value<first||value>last){toast('Choose a position time within the loaded 30-day window.');syncPositionControls();return;}positionEpoch=value;syncPositionControls();renderMap();updatePositionDetail();}
$('#position-time').addEventListener('change',()=>applyPositionEpoch(Date.parse($('#position-time').value+'Z')));$('#position-slider').addEventListener('input',()=>applyPositionEpoch(Date.parse(positionWindow+'T00:00:00Z')+Number($('#position-slider').value)*60000));$('#position-now').addEventListener('click',()=>{const now=Date.now(),first=Date.parse(positionWindow+'T00:00:00Z');if(now>=first&&now<first+positionDays*86400000){$('#live-clock').checked=true;applyPositionEpoch(now,{live:true});}else load(dateKey());});$('#show-path').addEventListener('change',()=>{renderMap();updatePositionDetail();});$('#clear-selection').addEventListener('click',()=>{selected=null;renderMap();renderTable();renderDetail();});$('#retry-positions').addEventListener('click',()=>{ephemeris.errors.clear();ephemeris.paused=false;renderMap();});

function setMode(mode){viewMode=mode;$('#earth-orientation-credit').textContent=mode==='3d'?'NASA Earth composites · orientation & sunlight follow UTC · Earth enlarged':'2D schematic · illustrated Earth and decorative bearings';$('#space-map .axis-label').textContent=mode==='3d'?'JPL HORIZONS · SELECT A DOT FOR ITS PREDICTED PATH':'SELECT AN ENCOUNTER TO EXPLORE';$('#space-map .map-corner').textContent=mode==='3d'?'EARTH EQUATORIAL VIEW · NORTH UP':'2D DISTANCE FIELD / EARTH-CENTERED';$('#space-map').dataset.viewMode=mode;$('#viewer3d-root').hidden=mode!=='3d';$('#mode-3d').setAttribute('aria-pressed',String(mode==='3d'));$('#mode-2d').setAttribute('aria-pressed',String(mode==='2d'));viewer?.setActive(mode==='3d');$('#viewer-status').textContent=mode==='3d'?'Equatorial view · rotate · zoom':viewerError||'2D distance schematic';renderMap();}
async function bootViewer(){try{const {EncounterViewer}=await import('./viewer3d.js');viewer=new EncounterViewer($('#viewer3d-root'),{onSelect:key=>{selected=key;renderMap();renderTable();renderDetail();},onFailure:message=>{viewerError=message;setMode('2d');$('#mode-3d').disabled=true;}});viewer.setMotion(motion);setMode(viewMode);}catch{viewerError='3D unavailable on this browser · 2D is ready';$('#mode-3d').disabled=true;setMode('2d');}}
$('#mode-3d').addEventListener('click',()=>{if(viewer)setMode('3d');});$('#mode-2d').addEventListener('click',()=>setMode('2d'));$('#reset-view').addEventListener('click',()=>{if(viewMode==='3d')viewer?.reset();else{zoom=1;renderMap();}});
$('#fullscreen-view').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.map-panel').requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser. The viewer still works here.');}});
function imageMarkup(image,confirmed){return `<figure class="asteroid-photo ${confirmed?'confirmed':'candidate'}"><a href="${esc(image.source)}" target="_blank" rel="noopener noreferrer"><img src="${esc(image.src)}" alt="${esc(image.title)}" loading="lazy" referrerpolicy="no-referrer"></a><figcaption><span class="media-badge">${confirmed?esc(image.type):image.illustrative?'Archive illustration · not a photograph':'Archive match · subject unverified'}</span><strong>${esc(image.title)}</strong><span>${esc(image.credit)}${image.date?' · '+esc(image.date):''}</span><p>${esc(confirmed?image.caption:image.description)}</p><a href="${esc(image.source)}" target="_blank" rel="noopener noreferrer">View original source ↗</a></figcaption></figure>`;}
function renderMedia(row){const box=$('#object-media');if(!box)return;const confirmed=reviewedImages[row.id]??[],state=photoState.get(row.id),query=searchDesignation(row);box.innerHTML=`<div class="media-heading"><span class="eyebrow">IMAGES OF THIS OBJECT</span><span>${confirmed.length?'Confirmed source':'Archive lookup'}</span></div>`+confirmed.map(i=>imageMarkup(i,true)).join('')+(!confirmed.length?`<div class="no-photo"><div class="rock" aria-hidden="true"></div><p>No confirmed image in the reviewed catalog.</p><small>Marker artwork is an illustration, not a photograph.</small></div>`:'')+`<div class="archive-results" role="status">${!state||state.loading?'Checking NASA’s image archive…':state.error?'NASA image search is temporarily unavailable.':state.candidates.length?`${state.candidates.length} archive matches below · verify the caption before treating one as a photo of this object.`:'No exact-designation matches found in NASA’s image library.'}</div>`+(state?.candidates??[]).map(i=>imageMarkup(i,false)).join('')+`<a class="media-search-link" href="https://images.nasa.gov/search?q=${encodeURIComponent(query)}&media=image" target="_blank" rel="noopener noreferrer">Search NASA images for ${esc(query)} ↗</a><p class="media-note">Historical imagery only. These sources do not cover every asteroid; missing imagery does not mean none exists elsewhere.</p>`;
 for(const img of box.querySelectorAll('img'))img.addEventListener('error',()=>{img.hidden=true;const p=document.createElement('p');p.className='image-error';p.textContent='Image preview unavailable. Open the original source.';img.parentElement.append(p);},{once:true});
 if(!state){photoState.set(row.id,{loading:true,candidates:[]});lookupImages(row).then(result=>{photoState.set(row.id,result);if(visible.find(r=>r.key===selected)?.id===row.id)renderMedia(row);}).catch(()=>{photoState.set(row.id,{error:true,candidates:[]});if(visible.find(r=>r.key===selected)?.id===row.id)renderMedia(row);});}
}
bootViewer();

$('#earth-closeup').addEventListener('click',()=>{if(viewer&&viewMode==='3d')viewer.focusEarth();else toast('Earth close-up is available in 3D space.');});
function tickLiveClock(){if(!$('#live-clock').checked||document.hidden||!positionWindow)return;const now=Date.now(),first=Date.parse(positionWindow+'T00:00:00Z');if(now<first||now>=first+positionDays*86400000-60000){$('#live-clock').checked=false;load(dateKey());return;}applyPositionEpoch(now,{live:true});}
$('#live-clock').addEventListener('change',tickLiveClock);
$('#position-time').addEventListener('focus',()=>{$('#live-clock').checked=false;});
setInterval(tickLiveClock,1000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tickLiveClock();});

$('#fit-field').addEventListener('click',()=>{referenceKey='';renderMap();viewer?.reset();});
